public static int findNthLeapYear(int Y, int N) {
    // Helper to determine if a year is a leap year
    java.util.function.IntPredicate isLeap = year -> {
        if (year % 400 == 0) return true;
        if (year % 100 == 0) return false;
        return year % 4 == 0;
    };

    int year = Y;
    int count = 0;
    while (count < N) {
        if (isLeap.test(year)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
    }
    // In theory we will always return inside the loop
    return year;
}

