public java.util.List<java.util.List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> result = new java.util.ArrayList<>();
    for (int num : nums) {
        if (result.isEmpty()) {
            java.util.List<Integer> list = new java.util.ArrayList<>();
            list.add(num);
            result.add(list);
            continue;
        }
        java.util.List<java.util.List<Integer>> newResult = new java.util.ArrayList<>();
        for (java.util.List<Integer> perm : result) {
            for (int i = 0; i <= perm.size(); i++) {
                java.util.List<Integer> newPerm = new java.util.ArrayList<>(perm);
                newPerm.add(i, num);
                newResult.add(newPerm);
            }
        }
        result = newResult;
    }
    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    int n = nums.length;
    boolean[] used = new boolean[n];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, used, current, result);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

