public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String base = strings.get(0);
    int baseLen = base.length();
    int maxLen = 0;
    // Use a set to avoid re-evaluating the same candidate
    HashSet<String> seen = new HashSet<>();
    for (int i = 0; i < baseLen; i++) {
        for (int j = i + 1; j <= baseLen; j++) {
            String cand = base.substring(i, j);
            if (!seen.add(cand)) {
                continue; // already processed
            }
            // Check if cand (or its reverse) appears in every string
            boolean ok = true;
            String rev = new StringBuilder(cand).reverse().toString();
            for (String s : strings) {
                if (!(s.contains(cand) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                int len = cand.length();
                if (len > maxLen) {
                    maxLen = len;
                }
            }
        }
    }
    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                // DFS/BFS to mark component
                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int cr = cell[0], cc = cell[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dRow[k];
                        int nc = cc + dCol[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return count;
}

