public static int countDoubles(int[] numbers) {
    int count = 0;
    for (int i = 0; i < numbers.length; i++) {
        for (int j = 0; j < numbers.length; j++) {
            if (i != j && numbers[i] == 2 * numbers[j]) {
                count++;
            }
        }
    }
    return count;
}

public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.HashSet<Integer> set = new java.util.HashSet<>();
    for (int num : numbers) {
        set.add(num);
    }
    int count = 0;
    for (int num : numbers) {
        if ((num & 1) == 0) { // num is even
            int half = num >> 1; // division by 2
            if (set.contains(half)) {
                count++;
            }
        }
    }
    return count;
}

