    for (int n : numbers) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int count = 0;
    for (int n : numbers) {
        if (n % 2 == 0) {
            int half = n / 2;
            if (freq.containsKey(half)) {
                if (half == n) { // n is 0, need at least two zeros
                    if (freq.get(n) > 1) {
                        count++;
                    }
                } else {
                    count++;
                }
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Convert coordinate arrays to string keys
    java.util.function.Function<int[], String> keyFunc = coords -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(',');
            sb.append(coords[i]);
        }
        return sb.toString();
    };
    String startKey = keyFunc.apply(start);
    String endKey = keyFunc.apply(end);

    // If start and end are the same point
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length != 2 * n) continue; // invalid path, skip
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String aKey = keyFunc.apply(a);
        String bKey = keyFunc.apply(b);
        adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }

    // BFS to find path from start to end
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            if (visited.add(nb)) {
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int i = 0; i < paths.length; i++) {
        int x1 = paths[i][0];
        int y1 = paths[i][1];
        int x2 = paths[i][2];
        int y2 = paths[i][3];
        String a = x1 + "#" + y1;
        String b = x2 + "#" + y2;
        graph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        graph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    String startKey = start[0] + "#" + start[1];
    String endKey = end[0] + "#" + end[1];

    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    visited.add(startKey);
    queue.offer(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = graph.get(current);
        if (neighbors != null) {
            for (String nb : neighbors) {
                if (!visited.contains(nb)) {
                    if (nb.equals(endKey)) {
                        return "can be travelled";
                    }
                    visited.add(nb);
                    queue.offer(nb);
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input coordinates
    if (start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    if (sx == ex && sy == ey) {
        return "can be travelled";
    }

    // Map a coordinate to a unique node id
    java.util.Map<Integer, java.util.List<Integer>> adj = new java.util.HashMap<>();

    // Helper to add undirected edge between two coordinates
    java.util.function.BiConsumer<int[], int[]> addEdge = (a, b) -> {
        int id1 = a[0] * n + a[1];
        int id2 = b[0] * n + b[1];
        adj.computeIfAbsent(id1, k -> new java.util.ArrayList<>()).add(id2);
        adj.computeIfAbsent(id2, k -> new java.util.ArrayList<>()).add(id1);
    };

    // Build adjacency list from paths
    for (int[] p : paths) {
        try {
            // Each path can be specified in two possible forms:
            // 1. [x1, y1, x2, y2] - explicit coordinates
            // 2. [x1, y1, x2, y2] with possibly fewer elements - we assume length 4
            if (p.length == 4) {
                int[] a = {p[0], p[1]};
                int[] b = {p[2], p[3]};
                // Ensure coordinates are within bounds
                if (a[0] < 0 || a[0] >= n || a[1] < 0 || a[1] >= n ||
                    b[0] < 0 || b[0] >= n || b[1] < 0 || b[1] >= n) {
