private static boolean dfs(int current, int target, boolean[][] adj, boolean[] visited) {
    if (current == target) {
        return true;
    }
    visited[current] = true;
    for (int next = 0; next < adj[current].length; next++) {
        if (adj[current][next] && !visited[next]) {
            if (dfs(next, target, adj, visited)) {
                return true;
            }
        }
    }
    return false;
}

public static String convertDatesToWeekdays(String date) {
    String[] parts = date.split(" ");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    String[] monthNames = {"January","February","March","April","May","June","July",
                           "August","September","October","November","December"};
    String[] weekDays = {"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};

    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.set(year, month - 1, day, 0, 0, 0);
    cal.set(java.util.Calendar.MILLISECOND, 0);
    int dayOfWeekIndex = cal.get(java.util.Calendar.DAY_OF_WEEK); // 1 = Sunday, 7 = Saturday
    String weekday = weekDays[dayOfWeekIndex - 1];

    return monthNames[month - 1] + " " + day + ", " + year + " is a " + weekday;
}

public static String convertDatesToWeekdays(String date) {
    String[] parts = date.split("\\s+");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    String[] monthNames = { "January", "February", "March", "April", "May", "June",
                            "July", "August", "September", "October", "November", "December" };
    String monthName = monthNames[month - 1];

    // Zeller's Congruence
    int m = month;
    int y = year;
    if (m <= 2) {
        m += 12;
        y -= 1;
    }
    int q = day;
    int K = y % 100;
    int J = y / 100;
    int h = (q + (13 * (m + 1)) / 5 + K + K / 4 + J / 4 + 5 * J) % 7;

    String[] weekdays = { "Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday" };
    String weekday = weekdays[h];

    return monthName + " " + day + ", " + year + " is a " + weekday;
}

