public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) rem += k;
        freq[rem]++;
    }
    if (freq[0] % 2 != 0) return false;
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) {
            if (freq[r] % 2 != 0) return false;
        } else {
            if (freq[r] != freq[complement]) return false;
        }
    }
    return true;
}

