    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // occurs when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0) return false;                     // invalid divisor
    int n = arr.length;
    if (n % 2 != 0) return false;                 // must pair all elements

    int[] freq = new int[k];
    for (int val : arr) {
        int r = ((val % k) + k) % k;              // positive remainder
        freq[r]++;
    }

    if (freq[0] % 2 != 0) return false;           // remainder 0 must pair among themselves

    if (k % 2 == 0 && freq[k / 2] % 2 != 0)       // special case when k is even
        return false;

    int half = k / 2;
    for (int r = 1; r <= half; r++) {
        int opp = k - r;
        if (r == opp) continue;                  // already handled when k even
        if (freq[r] != freq[opp]) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0) {
        return false; // division by zero or negative divisor is not allowed
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        count[r]++;
    }
    // Elements with remainder 0 must be paired among themselves
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k is even, elements with remainder k/2 must also pair among themselves
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For the remaining remainders, each count must match its complementary remainder
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled for k even
            continue;
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0) {
        return false; // divisor must be positive
    }
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // ensure non-negative remainder
        freq[r]++;
    }

    // remainder 0 must pair with 0
    if ((freq[0] & 1) == 1) { // odd number of zeros
        return false;
    }

    int upper = k / 2;
    for (int r = 1; r < upper; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }

    // if k is even, remainder k/2 must also pair with itself
    if (k % 2 == 0 && (freq[upper] & 1) == 1) {
        return false;
    }

    return true;
}

