public String sortString(String s) {
    int[] freq = new int[26];
    for (int i = 0; i < s.length(); i++) {
        freq[s.charAt(i) - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    while (result.length() < total) {
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
        for (int i = 25; i >= 0; i--) {
            if (freque[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }
    int total = s.length();
    StringBuilder sb = new StringBuilder();
    while (total > 0) {
        int last = -1;
        // Ascending pass: pick smallest character
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                sb.append((char) ('a' + i));
                count[i]--;
                total--;
                last = i;
                break;
            }
        }
        if (total == 0) break;
        // Continue ascending picking smallest > last
        for (int i = last + 1; i < 26; i++) {
            while (count[i] > 0) {
                sb.append((char) ('a' + i));
                count[i]--;
                last = i;
                total--;
            }
        }
        if (total == 0) break;
        // Descending pass: pick largest character
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                sb.append((char) ('a' + i));
                count[i]--;
                last = i;
                total--;
                break;
            }
        }
        if (total == 0) break;
        // Continue descending picking largest < last
        for (int i = last - 1; i >= 0; i--) {
            while (count[i] > 0) {
                sb.append((char) ('a' + i));
                count[i]--;
                last = i;
                total--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // sumsByCount[k] contains all possible sums of subsets with size k
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] sumsByCount = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sumsByCount[i] = new java.util.HashSet<>();
    }
    sumsByCount[0].add(0);

    for (int num : nums) {
        for (int cnt = n - 1; cnt >= 0; cnt--) {
            for (int sum : sumsByCount[cnt]) {
                sumsByCount[cnt + 1].add(sum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (int) ((totalSum * k) / n);
        if (sumsByCount[k].contains(target)) {
            return true;
        }
    }
    return false;
}

