public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    @SuppressWarnings("unchecked")
    HashSet<Integer>[] subsetSums = new HashSet[n + 1];
    subsetSums[0] = new HashSet<>();
    subsetSums[0].add(0);

    int used = 0;
    for (int num : nums) {
        used++;
        // Iterate k backwards to avoid using the same element more than once
        for (int k = Math.min(used, n - 1); k >= 1; k--) {
            if (subsetSums[k] == null) subsetSums[k] = new HashSet<>();
            HashSet<Integer> prevSet = subsetSums[k - 1];
            if (prevSet == null) continue;
            for (int sum : prevSet) {
                subsetSums[k].add(sum + num);
            }
        }
    }

    for (int k = 1; k <= n - 1; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (subsetSums[k] != null && subsetSums[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    // Compute total sum
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // If totalSum is 0, any non-empty subset will have average 0, so check quickly
    if (totalSum == 0) return true;
    // Prepare DP: dp[size][sum] == true if a subset of given size achieves sum
    int maxSum = totalSum; // sum of all elements
    boolean[][] dp = new boolean[n + 1][maxSum + 1];
    dp[0][0] = true;
    for (int val : nums) {
        // iterate sizes backwards to avoid reuse
        for (int size = n - 1; size >= 0; size--) {
            for (int sum = 0; sum <= maxSum - val; sum++) {
                if (dp[size][sum]) {
                    dp[size + 1][sum + val] = true;
                }
            }
        }
    }
    // Try each possible subset size up to n/2
    for (int k = 1; k <= n / 2; k++) {
        // totalSum * k must be divisible by n for integer average
        if ((totalSum * k) % n == 0) {
            int targetSum = (totalSum * k) / n;
            if (dp[k][targetSum]) return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n + 3]; // dp[i] represents the min cost to reach the top from step i
    for (int i = n - 1; i >= 0; i--) {
        dp[i] = cost[i] + Math.min(dp[i + 1], dp[i + 2]);
    }
    return Math.min(dp[0], dp[1]); // can start from step 0 or step 1
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    int curr = 0;
    for (int i = 2; i <= n; i++) {
        curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return curr;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int last = cost[0];
    int secondLast = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(last, secondLast);
        last = secondLast;
        secondLast = current;
    }
    return Math.min(last, secondLast);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return Math.min(0, cost[0]); // in most definitions, you can start at step 0 or 1, so cost 0 to reach top
    int a = cost[0];
    int b = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(a, b);
        a = b;
        b = current;
    }
    return Math.min(a, b);
}

