public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = 0;
    int maskLimit = total - 1;
    int count = 0;

    // Build mask for the first window
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    if (!seen[mask]) {
        seen[mask] = true;
        count++;
    }

    // Slide the window through the string
    for (int i = k; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            count++;
            if (count == total) { // early exit
                return true;
            }
        }
    }

    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;
    for (int i = 0; i <= n - k; i++) {
        int val = 0;
        for (int j = 0; j < k; j++) {
            val = (val << 1) | (s.charAt(i + j) - '0');
        }
        if (!seen[val]) {
            seen[val] = true;
            count++;
            if (count == total) return true;
        }
    }
    return false;
}

