    int current = 0;
    // first k characters
    for (int i = 0; i < k; i++) {
        current = (current << 1) | (s.charAt(i) - '0');
    }
    seen[current] = true;
    int count = 1;
    for (int i = k; i < n; i++) {
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[current]) {
            seen[current] = true;
            count++;
            if (count == total) return true;
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true; // trivially true for empty substrings
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;                // number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;               // to keep only k bits
    int val = 0;                        // current window value
    int count = 0;                      // distinct codes seen
    for (int i = 0; i < n; i++) {
        // shift left and add new bit
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {              // window is full
            if (!seen[val]) {
                seen[val] = true;
                count++;
                if (count == total) return true; // early exit
            }
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }
    int total = 1 << k;          // total number of binary strings of length k
    boolean[] seen = new boolean[total];
    int seenCount = 0;
    int mask = total - 1;       // mask to keep only k bits
    int cur = 0;
    for (int i = 0; i < s.length(); i++) {
        cur = ((cur << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {        // we have a complete window of length k
            if (!seen[cur]) {
                seen[cur] = true;
                seenCount++;
                if (seenCount == total) {
                    return true; // all possible codes found
                }
            }
        }
    }
    return false; // not all codes were seen
}

