public int minInsertions(String s) {
    int result = 0;
    int imbalance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            imbalance++;
        } else {
            if (imbalance == 0) {
                result++; // need to insert '(' before this ')'
            } else {
                imbalance--;
            }
        }
    }
    result += imbalance; // remaining '(' need matching ')'
    return result;
}

public int minInsertions(String s) {
    int leftGap = 0; // number of unmatched '(' that need a matching ')'
    int res = 0;    // count of insertions needed
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == '(') {
            leftGap++;
        } else { // ch == ')'
            leftGap--;
            if (leftGap == -1) { // need a '(' before this ')'
                res++;          // insert '('
                leftGap = 0;    // reset gap after matching
            }
        }
    }
    // Any remaining unmatched '(' need ')' inserted
    return res + leftGap;
}

public int minInsertions(String s) {
    int needed = 0;   // number of '(' needed to match future ')'
    int answer = 0;   // total number of insertions required

    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == '(') {
            needed++;
        } else { // ch == ')'
            needed--;
            if (needed < 0) { // more ')' than '('
                answer++;
                needed = 0; // we inserted a '(' before this ')'
            }
        }
    }

    // any remaining '(' need closing ')'
    return answer + needed;
}

public int minInsertions(String s) {
    int balance = 0;
    int inserts = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                inserts++; // need to insert a '(' before this ')'
            } else {
                balance--; // match this ')'
            }
        }
    }
    return inserts + balance; // need 'balance' many ')' after the string
}

public int minInsertions(String s) {
    int openNeeded = 0;  // number of '(' we need to balance upcoming ')'
    int insertions = 0;  // total insertions made so far

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            openNeeded++;  // we have one more '(' to match
        } else if (c == ')') {
            if (openNeeded > 0) {
                // match this ')' with a previous '('
                openNeeded--;
            } else {
                // no '(' to match, need to insert a '(' before this ')'
                insertions++;
            }
        }
    }

    // Any remaining unmatched '(' need a ')' to pair up
    return insertions + openNeeded;
}

public int minOperations(int n) {
    // Calculate the starting index for surplus elements
    int start = (n + 1) / 2;   // integer division
    // Number of surplus indices
    int terms = n - start;
    // Total operations equal to start * terms
    return start * terms;
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    if ((n & 1) == 0) { // even
        long half = n / 2L;
        return (int) (half * half);
    } else { // odd
        long nn = (long) n * n;
        return (int) ((nn - 1) / 4);
    }
}

public int minOperations(int n) {
    long half = n / 2L;
    if (n % 2 == 0) {
        return (int) (half * half);
    } else {
        return (int) (half * (half + 1));
    }
}

public int minOperations(int n) {
    int k = n / 2; // floor division
    if (n % 2 == 0) {
        return k * k;
    } else {
        return k * (k + 1);
    }
}

public int minOperations(int n) {
    long answer = 0;
    int startIndex = (n + 1) / 2; // ceil(n/2)
    for (int i = startIndex; i < n; i++) {
        answer += (2L * i + 1L - n);
    }
    return (int) answer;
}

