public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int maxSize = 50; // Enough for int range
    int[] fibs = new int[maxSize];
    int fibCount = 0;
    fibs[fibCount++] = 1;
    if (k > 1) {
        fibs[fibCount++] = 1;
    } else {
        // k == 1, only one Fibonacci number needed
        return 1;
    }
    while (true) {
        long next = (long) fibs[fibCount - 1] + fibs[fibCount - 2];
        if (next > k) {
            break;
        }
        fibs[fibCount++] = (int) next;
    }

    // Greedy: pick the largest Fibonacci numbers first
    int remaining = k;
    int count = 0;
    for (int i = fibCount - 1; i >= 0 && remaining > 0; i--) {
        if (fibs[i] <= remaining) {
            remaining -= fibs[i];
            count++;
        }
    }
    return count;
}

