public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i * i != n) {
                large.add(n / i);
            }
        }
    }
    // Combine small factors in ascending order and large factors in descending order
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) return -1;
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idx = k - small.size() - 1; // 0-based index in descending order
        return large.get(large.size() - 1 - idx);
    }
}

public int kthFactor(int n, int k) {
    int limit = (int)Math.sqrt(n);
    int[] small = new int[limit + 1];
    int[] large = new int[limit + 1];
    int sCnt = 0, lCnt = 0;
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small[sCnt++] = i;
            int counterpart = n / i;
            if (i != counterpart) {
                large[lCnt++] = counterpart;
            }
        }
    }
    if (k <= sCnt) {
        return small[k - 1];
    }
    int remaining = k - sCnt;
    if (remaining <= lCnt) {
        int indexInLarge = lCnt - remaining;
        return large[indexInLarge];
    }
    return -1;
}

public int kthFactor(int n, int k) {
    List<Integer> low = new ArrayList<>();
    List<Integer> high = new ArrayList<>();
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            low.add(i);
            int div = n / i;
            if (div != i) {
                high.add(div);
            }
        }
    }
    // Combine in ascending order: low ascending, then high reversed
    int total = low.size() + high.size();
    if (k > total) {
        return -1;
    }
    int index = k - 1;
    if (index < low.size()) {
        return low.get(index);
    } else {
        int highIndex = high.size() - 1 - (index - low.size());
        return high.get(highIndex);
    }
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (i != other) {
                large.add(other);
            }
        }
    }
    int smallSize = small.size();
    int total = smallSize + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= smallSize) {
        return small.get(k - 1);
    }
    // k-th factor lies in the 'large' list, which is in descending order relative to ascending order of factors.
    int indexInLarge = k - smallSize - 1;
    return large.get(large.size() - 1 - indexInLarge);
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    return k <= factors.size() ? factors.get(k - 1) : -1;
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Math.abs(c - top) == 32) { // 'a' to 'A' difference is 32
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

