public int maxUniqueSplit(String s) {
    class Solver {
        int best = 0;
        void dfs(int pos, Set<String> used, int cnt) {
            if (pos == s.length()) {
                if (cnt > best) best = cnt;
                return;
            }
            for (int end = pos + 1; end <= s.length(); end++) {
                String part = s.substring(pos, end);
                if (!used.contains(part)) {
                    used.add(part);
                    dfs(end, used, cnt + 1);
                    used.remove(part);
                }
            }
        }
    }
    Solver solver = new Solver();
    solver.dfs(0, new HashSet<>(), 0);
    return solver.best;
}

public int maxUniqueSplit(String s) {
    return dfs(s, 0, new java.util.HashSet<>());
}

private int dfs(String s, int index, java.util.Set<String> seen) {
    if (index == s.length()) {
        return 0;
    }
    int best = Integer.MIN_VALUE;
    for (int i = index + 1; i <= s.length(); i++) {
        String sub = s.substring(index, i);
        if (!seen.contains(sub)) {
            seen.add(sub);
            int res = 1 + dfs(s, i, seen);
            if (res > best) {
                best = res;
            }
            seen.remove(sub);
        }
    }
    return best;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    if (n == 0) return 0;
    int maxPieces = 1; // at least one piece (the whole string)
    int limit = 1 << (n - 1);
    for (int mask = 0; mask < limit; mask++) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        int start = 0;
        boolean valid = true;
        int pieces = 0;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) {
                String sub = s.substring(start, i + 1);
                if (!seen.add(sub)) {
                    valid = false;
                    break;
                }
                pieces++;
                start = i + 1;
            }
        }
        if (!valid) continue;
        String sub = s.substring(start, n);
        if (!seen.add(sub)) continue;
        pieces++;
        if (pieces > maxPieces) {
            maxPieces = pieces;
        }
    }
    return maxPieces;
}

public int maxUniqueSplit(String s) {
    int[] best = {0};
    dfs(s, 0, new java.util.HashSet<>(), best);
    return best[0];
}

private void dfs(String s, int pos, java.util.Set<String> used, int[] best) {
    if (pos == s.length()) {
        if (used.size() > best[0]) {
            best[0] = used.size();
        }
        return;
    }
    for (int i = pos + 1; i <= s.length(); i++) {
        String sub = s.substring(pos, i);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, i, used, best);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    return dfs(0, s, new java.util.HashSet<String>());
}

private int dfs(int pos, String s, java.util.Set<String> seen) {
    if (pos == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (seen.contains(sub)) {
            continue;
        }
        seen.add(sub);
        int res = 1 + dfs(end, s, seen);
        if (res > max) {
            max = res;
        }
        seen.remove(sub);
    }
    return max;
}

