public String getSmallestString(int n, int k) {
    // If the desired sum is impossible, return an empty string.
    int minSum = n;          // all 'a's
    int maxSum = n * 26;     // all 'z's
    if (k < minSum || k > maxSum) {
        return "";
    }
    char[] result = new char[n];
    // start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int diff = k - minSum; // additional value we need to distribute

    // increase letters from the end to keep lexicographically minimal string
    for (int i = n - 1; i >= 0 && diff > 0; i--) {
        int add = Math.min(25, diff);          // each position can add at most 25 (to 'z')
        result[i] = (char)('a' + add);
        diff -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    // Start with all 'a's: base value n
    char[] res = new char[n];
    for (int i = 0; i < n; i++) res[i] = 'a';
    int remaining = k - n; // extra value we need to distribute
    // Distribute from the rightmost position to keep the string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max we can add to this position
        res[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(res);
}

