public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCnt = 0;
        for (int num : nums) {
            bitCnt += (num >> i) & 1;
        }
        if (bitCnt % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            if (((num >> i) & 1) == 1) {
                sum++;
            }
        }
        if (sum % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        ones = (ones ^ num) & ~twos;
        twos = (twos ^ num) & ~ones;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int x : nums) {
        // Update 'ones' with new bits and exclude those that are in 'twos'
        ones = (ones ^ x) & ~twos;
        // Update 'twos' with new bits and exclude those that are in 'ones'
        twos = (twos ^ x) & ~ones;
    }
    return ones;
}

