        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    if (high < 0) {
        return result;
    }
    // 0 is a stepping number if within bounds
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    Queue<Long> queue = new LinkedList<>();

    // Initialize queue with single digit numbers 1-9
    for (int d = 1; d <= 9; d++) {
        if (d > high) {
            break;
        }
        queue.offer((long) d);
        if (d >= low) {
            result.add(d);
        }
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();
        int lastDigit = (int) (current % 10);

        // Append lastDigit - 1 if valid
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add((int) next);
                }
            }
        }

        // Append lastDigit + 1 if valid
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add((int) next);
                }
            }
        }
    }

    Collections.sort(result);
    return result;
}

