        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) {
        return new int[0];
    }
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int totalDiagonals = m + n - 1;
    for (int d = 0; d < totalDiagonals; d++) {
        int rowStart = Math.max(0, d - (n - 1));
        int rowEnd = Math.min(m - 1, d);
        if (d % 2 == 0) {
            for (int r = rowEnd; r >= rowStart; r--) {
                int c = d - r;
                result[index++] = mat[r][c];
            }
        } else {
            for (int r = rowStart; r <= rowEnd; r++) {
                int c = d - r;
                result[index++] = mat[r][c];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) return new int[0];
    int n = mat[0].length;
    if (n == 0) return new int[0];
    int[] res = new int[m * n];
    int idx = 0;
    int maxSum = m + n - 2;
    for (int s = 0; s <= maxSum; s++) {
        int rowStart = Math.max(0, s - (n - 1));
        int rowEnd = Math.min(m - 1, s);
        if ((s & 1) == 0) { // even sum: traverse from rowEnd down to rowStart
            for (int i = rowEnd; i >= rowStart; i--) {
                int j = s - i;
                res[idx++] = mat[i][j];
            }
        } else { // odd sum: traverse from rowStart up to rowEnd
            for (int i = rowStart; i <= rowEnd; i++) {
                int j = s - i;
                res[idx++] = mat[i][j];
            }
        }
    }
    return res;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int idx = 0;

    for (int k = 0; k < rows + cols - 1; k++) {
        int startRow = Math.max(0, k - cols + 1);
        int endRow = Math.min(k, rows - 1);

        if (k % 2 == 0) {
            for (int i = endRow; i >= startRow; i--) {
                int j = k - i;
                result[idx++] = mat[i][j];
            }
        } else {
            for (int i = startRow; i <= endRow; i++) {
                int j = k - i;
                result[idx++] = mat[i][j];
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) return new int[0];
    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];
    int row = 0, col = 0, idx = 0;
    boolean up = true;
    while (idx < m * n) {
        result[idx++] = mat[row][col];
        if (up) {
            if (col == n - 1) {
                row++;
                up = false;
            } else if (row == 0) {
                col++;
                up = false;
            } else {
                row--;
                col++;
            }
        } else {
            if (row == m - 1) {
                col++;
                up = true;
            } else if (col == 0) {
                row++;
                up = true;
            } else {
                row++;
                col--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int l = i + 1, r = digits.length - 1;
    while (l < r) {
        char t = digits[l];
        digits[l] = digits[r];
        digits[r] = t;
        l++;
        r--;
    }
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    // Find the rightmost index i such that digits[i] < digits[i + 1]
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // No larger permutation exists
        return -1;
    }
    // Find rightmost index j greater than i such that digits[j] > digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse the subarray from i+1 to end
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        char swap = digits[left];
        digits[left] = digits[right];
        digits[right] = swap;
        left++;
        right--;
    }
    // Convert back to integer
    return Integer.parseInt(new String(digits));
}

