public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    result.addAll(build(n, n));
    return result;
}

private static List<String> build(int len, int targetLen) {
    List<String> res = new ArrayList<>();
    if (len == 0) {
        res.add("");
        return res;
    }
    if (len == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    List<String> inner = build(len - 2, targetLen);
    String[][] pairs = {
        {"0", "0"}, {"1", "1"}, {"6", "9"}, {"8", "8"}, {"9", "6"}
    };
    for (String[] pair : pairs) {
        // Skip numbers with leading zero unless length==1
        if (pair[0].equals("0") && len == targetLen) {
            continue;
        }
        for (String sub : inner) {
            res.add(pair[0] + sub + pair[1]);
        }
    }
    return res;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    List<String> pairs = Arrays.asList("00", "11", "69", "88", "96");
    List<Character> mid = Arrays.asList('0', '1', '8');
    char[] arr = new char[n];
    backtrack(arr, 0, n - 1, result, pairs, mid);
    return result;
}

private static void backtrack(char[] arr, int left, int right, List<String> result,
                              List<String> pairs, List<Character> mid) {
    if (left > right) {
        result.add(new String(arr));
        return;
    }
    if (left == right) {
        for (char c : mid) {
            arr[left] = c;
            backtrack(arr, left + 1, right - 1, result, pairs, mid);
        }
    } else {
        for (String p : pairs) {
            if (left == 0 && p.charAt(0) == '0') continue; // No leading zero for length > 1
            arr[left] = p.charAt(0);
            arr[right] = p.charAt(1);
            backtrack(arr, left + 1, right - 1, result, pairs, mid);
        }
    }
}

