}

private static List<String> generate(int remaining, int total) {
    if (remaining == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (remaining == 1) {
        return List.of("0", "1", "8");
    }

    List<String> result = new ArrayList<>();
    List<String> middle = generate(remaining - 2, total);
    String[][] pairs = {
        {"0", "0"},
        {"1", "1"},
        {"6", "9"},
        {"8", "8"},
        {"9", "6"}
    };

    for (String m : middle) {
        for (String[] pair : pairs) {
            if (remaining == total && pair[0].equals("0")) {
                continue;
            }
            result.add(pair[0] + m + pair[1]);
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    char[][] pairs = {{'0','0'},{'1','1'},{'8','8'},{'6','9'},{'9','6'}};
    char[] arr = new char[n];
    backtrack(arr, 0, n-1, result, n, pairs);
    return result;
}

private static void backtrack(char[] arr, int left, int right, List<String> result, int n, char[][] pairs) {
    if (left > right) {
        result.add(new String(arr));
        return;
    }
    if (left == right) {
        for (char c : new char[]{'0','1','8'}) {
            arr[left] = c;
            backtrack(arr, left+1, right-1, result, n, pairs);
        }
    } else {
        for (char[] p : pairs) {
            if (left == 0 && n > 1 && p[0] == '0') continue;
            arr[left] = p[0];
            arr[right] = p[1];
            backtrack(arr, left+1, right-1, result, n, pairs);
        }
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];

    // Using the shoelace formula to compute twice the signed area
    int area2 = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    return area2 != 0;
}

