public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int max = 1;
    int count = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char current = s.charAt(i);
        if (current == prev) {
            count++;
        } else {
            if (count > max) {
                max = count;
            }
            prev = current;
            count = 1;
        }
    }
    if (count > max) {
        max = count;
    }
    return max;
}

